import { useId, useMemo } from 'react';
import { Badge, EmptyState, cn, useI18n } from '@gntik-ai/ui';
import { CalendarDays, ChevronRight, Clock } from '@gntik-ai/icons';
import { useSchedulingClock } from '../shared/useSchedulingClock';
import { TimeZoneLabel } from '../shared/CalendarHeader';
import { EventTile } from '../shared/EventTile';
import { addDays, dayKey, formatDay, formatRange, sameDay, type HourCycle } from '../shared/dates';
import { defaultEventKinds, groupByDay, kindOf, TONE, type EventKind, type ScheduleEvent } from '../shared/events';
import { sampleEvents, sampleToday } from '../shared/fixtures';

export interface AgendaListProps {
  events?: ScheduleEvent[];
  /** Display time zone; defaults to the I18nProvider zone (system outside a provider). */
  timeZone?: string;
  /** Clock used for event ranges; defaults to the provider or runtime locale. */
  hourCycle?: HourCycle;
  /** The app's "today": labels the Today/Tomorrow groups. */
  today?: Date;
  /** Only events on or after this day. Defaults to `today`; pass null for all. */
  from?: Date | null;
  /** Number of days shown from `from`. Default 7; null for no limit. */
  days?: number | null;
  /** Makes each row a button. */
  onEventClick?: (event: ScheduleEvent) => void;
  kinds?: Record<string, EventKind>;
  title?: string;
  /** Max height of the scrolling list in px. */
  maxHeight?: number;
  emptyTitle?: string;
  emptyDescription?: string;
  /** Heading level of the title, to fit the page outline (default h3); inner headings use the next level. */
  titleAs?: 'h2' | 'h3' | 'h4';
  className?: string;
}

/** Upcoming scheduled work grouped by day, each row with a kind tile, time range and location. */
export function AgendaList({
  events = sampleEvents,
  timeZone: timeZoneProp,
  hourCycle: hourCycleProp,
  today = sampleToday,
  from,
  days = 7,
  onEventClick,
  kinds = defaultEventKinds,
  title: titleProp,
  maxHeight,
  emptyTitle: emptyTitleProp,
  emptyDescription: emptyDescriptionProp,
  titleAs: TitleTag = 'h3',
  className,
}: AgendaListProps) {
  const { t, locale, timeZone: providerZone } = useI18n();
  const timeZone = timeZoneProp ?? providerZone;
  const clock = useSchedulingClock(hourCycleProp);
  const title = titleProp ?? t('calendar.agenda');
  const emptyTitle = emptyTitleProp ?? t('calendar.emptyTitle');
  const emptyDescription = emptyDescriptionProp ?? t('calendar.emptyDescription');
  const SubTag = TitleTag === 'h2' ? 'h3' : TitleTag === 'h3' ? 'h4' : 'h5';
  const uid = useId();
  const start = from === undefined ? today : from;
  const groups = useMemo(() => {
    const first = start ? dayKey(start, timeZone) : null;
    const last = start && days != null ? dayKey(addDays(start, days - 1, timeZone), timeZone) : null;
    return [...groupByDay(events, timeZone).entries()]
      .filter(([key]) => (first == null || key >= first) && (last == null || key <= last))
      .sort(([a], [b]) => a.localeCompare(b));
  }, [events, start, days, timeZone]);

  const dayLabel = (d: Date) => {
    if (sameDay(d, today, timeZone)) return `${t('calendar.today')} · ${formatDay(d, locale, timeZone)}`;
    if (sameDay(d, addDays(today, 1, timeZone), timeZone))
      return `${t('calendar.tomorrow')} · ${formatDay(d, locale, timeZone)}`;
    return formatDay(d, locale, timeZone);
  };

  return (
    <section
      aria-label={timeZone === 'system' ? title : undefined}
      aria-labelledby={timeZone === 'system' ? undefined : `${uid}-title ${uid}-zone`}
      className={cn('overflow-hidden rounded-xl border border-border bg-card', className)}
    >
      <div
        className={cn(
          'flex items-center justify-between gap-3 border-b border-border px-4 py-3 sm:px-5',
          timeZone !== 'system' && 'flex-wrap',
        )}
      >
        {timeZone === 'system' ? (
          <TitleTag className="text-[15px] font-semibold tracking-tight text-foreground">{title}</TitleTag>
        ) : (
          <div className="min-w-0">
            <TitleTag id={`${uid}-title`} className="text-[15px] font-semibold tracking-tight text-foreground">
              {title}
            </TitleTag>
            <TimeZoneLabel id={`${uid}-zone`} timeZone={timeZone} referenceDate={start ?? today} />
          </div>
        )}
        <span className="font-mono text-[11px] text-muted-foreground">
          {groups.reduce((n, [, list]) => n + list.length, 0)} scheduled
        </span>
      </div>
      {groups.length === 0 ? (
        <EmptyState
          icon={CalendarDays}
          title={emptyTitle}
          titleAs={TitleTag === 'h2' ? 'h3' : 'h4'}
          description={emptyDescription}
          className="py-12"
        />
      ) : (
        <div
          style={maxHeight ? { maxHeight } : undefined}
          tabIndex={maxHeight ? 0 : undefined}
          role={maxHeight ? 'region' : undefined}
          aria-label={maxHeight ? `${title} list` : undefined}
          className="overflow-y-auto focus-ring-inset"
        >
          {groups.map(([key, list]) => {
            const first = list[0];
            if (!first) return null;
            const headingId = `${uid}-${key}`;
            return (
              <div key={key}>
                <SubTag
                  id={headingId}
                  className="border-b border-border bg-secondary/30 px-4 py-2 font-mono text-[11px] tracking-wide text-muted-foreground uppercase sm:px-5"
                >
                  {dayLabel(first.start)}
                </SubTag>
                <ul
                  aria-labelledby={headingId}
                  className="divide-y divide-border border-b border-border last:border-b-0"
                >
                  {list.map((event) => {
                    const kind = kindOf(event, kinds);
                    const range = formatRange(event.start, event.end, clock.locale, clock.hourCycle, timeZone);
                    const content = (
                      <>
                        <EventTile kind={kind} />
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[13px] font-semibold text-foreground">
                            {event.title}
                          </span>
                          <span className="mt-0.5 flex items-center gap-1.5 font-mono text-[11.5px] text-muted-foreground">
                            <Clock size={12} aria-hidden className="shrink-0" />
                            <span>{range}</span>
                            {event.location && (
                              <>
                                <span aria-hidden>·</span>
                                <span className="truncate">{event.location}</span>
                              </>
                            )}
                          </span>
                        </span>
                        <Badge tone={TONE[kind.tone].badge} size="sm" className="hidden sm:inline-flex">
                          {kind.label}
                        </Badge>
                      </>
                    );
                    const row = 'flex w-full items-center gap-3.5 px-4 py-3 text-start sm:px-5';
                    return (
                      <li key={event.id}>
                        {onEventClick ? (
                          <button
                            type="button"
                            onClick={() => onEventClick(event)}
                            className={cn(
                              row,
                              'group transition-colors hover:bg-accent/30 focus-ring-inset motion-reduce:transition-none',
                            )}
                          >
                            {content}
                            <ChevronRight
                              size={16}
                              aria-hidden
                              className="shrink-0 text-muted-foreground transition-colors group-hover:text-foreground rtl:-scale-x-100"
                            />
                          </button>
                        ) : (
                          <div className={row}>{content}</div>
                        )}
                      </li>
                    );
                  })}
                </ul>
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}

import type { ReactNode } from 'react';
import { Button, IconButton, useI18n, formatTimeZoneLabel } from '@gntik-ai/ui';
import { ChevronLeft, ChevronRight } from '@gntik-ai/icons';

export interface CalendarHeaderProps {
  titleId: string;
  timeZone?: string;
  referenceDate?: Date;
  title: string;
  subtitle?: string;
  prevLabel: string;
  nextLabel: string;
  onPrev: () => void;
  onNext: () => void;
  onToday: () => void;
  actions?: ReactNode;
}

/** Title + previous / today / next navigation + caller actions. */
export function CalendarHeader({
  timeZone = 'system',
  referenceDate,
  titleId,
  title,
  subtitle,
  prevLabel,
  nextLabel,
  onPrev,
  onNext,
  onToday,
  actions,
}: CalendarHeaderProps) {
  const { t } = useI18n();
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3 sm:px-5">
      <div className="min-w-0">
        <h3
          id={titleId}
          aria-live="polite"
          className="truncate text-[15px] font-semibold tracking-tight text-foreground"
        >
          {title}
        </h3>
        <TimeZoneLabel id={`${titleId}-zone`} timeZone={timeZone} referenceDate={referenceDate} />
        {subtitle && <p className="mt-0.5 truncate font-mono text-[11px] text-muted-foreground">{subtitle}</p>}
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <div className="flex items-center gap-1">
          <IconButton icon={ChevronLeft} label={prevLabel} variant="secondary" size="sm" onClick={onPrev} />
          <Button variant="secondary" size="sm" onClick={onToday}>
            {t('calendar.today')}
          </Button>
          <IconButton icon={ChevronRight} label={nextLabel} variant="secondary" size="sm" onClick={onNext} />
        </div>
        {actions}
      </div>
    </div>
  );
}

/** Shared, wrapping zone caption for calendar and agenda headers. */
export function TimeZoneLabel({
  id,
  timeZone,
  referenceDate,
}: {
  id?: string;
  timeZone: string;
  referenceDate?: Date;
}) {
  const { t } = useI18n();
  if (timeZone === 'system') return null;
  const zone = timeZone === 'UTC' ? 'UTC' : `${timeZone} (${formatTimeZoneLabel(timeZone, referenceDate, 'en-US')})`;
  return (
    <p id={id} className="mt-0.5 break-words text-[11px] text-muted-foreground">
      {t('scheduling.timeZone', { zone })}
    </p>
  );
}

import { cn } from '@gntik-ai/ui';
import { TONE, type EventKind } from './events';

/** Square type tile (no avatars on scheduled work). */
export function EventTile({ kind, className }: { kind: EventKind; className?: string }) {
  const Glyph = kind.icon;
  const tone = TONE[kind.tone];
  return (
    <span
      aria-hidden
      className={cn(
        'inline-flex size-9 shrink-0 items-center justify-center rounded-lg',
        tone.soft,
        tone.icon,
        className,
      )}
    >
      <Glyph size={17} />
    </span>
  );
}

/** Native-Date helpers for scheduling. All optional zones default to the runtime clock. */
import { fromZonedParts, zonedParts, type WeekDay } from '@gntik-ai/ui';

const pad = (n: number) => String(n).padStart(2, '0');

/** Midnight in the display zone, normalizing calendar arithmetic before DST conversion. */
function calendarDate(year: number, month: number, day: number, zone = 'system'): Date {
  if (zone === 'system') return new Date(year, month - 1, day);
  const normalized = new Date(0);
  normalized.setUTCFullYear(year, month - 1, day);
  const parts = zonedParts(normalized, 'UTC');
  return fromZonedParts(parts, zone)!;
}

export function dayKey(d: Date, zone = 'system'): string {
  const p = zonedParts(d, zone);
  return `${p.year}-${pad(p.month)}-${pad(p.day)}`;
}
export function startOfDay(d: Date, zone = 'system'): Date {
  const p = zonedParts(d, zone);
  return calendarDate(p.year, p.month, p.day, zone);
}
export function addDays(d: Date, n: number, zone = 'system'): Date {
  const p = zonedParts(d, zone);
  return calendarDate(p.year, p.month, p.day + n, zone);
}
export function addMonths(d: Date, n: number, zone = 'system'): Date {
  const p = zonedParts(d, zone);
  return calendarDate(p.year, p.month + n, 1, zone);
}
export function startOfMonth(d: Date, zone = 'system'): Date {
  return addMonths(d, 0, zone);
}
export function sameDay(a: Date, b: Date, zone = 'system'): boolean {
  return dayKey(a, zone) === dayKey(b, zone);
}
export function sameMonth(a: Date, b: Date, zone = 'system'): boolean {
  const p = zonedParts(a, zone),
    q = zonedParts(b, zone);
  return p.year === q.year && p.month === q.month;
}
export function weekday(d: Date, zone = 'system'): WeekDay {
  const p = zonedParts(d, zone);
  return new Date(Date.UTC(p.year, p.month - 1, p.day)).getUTCDay() as WeekDay;
}
export function startOfWeek(d: Date, weekStartsOn: WeekDay, zone = 'system'): Date {
  return addDays(d, -((weekday(d, zone) - weekStartsOn + 7) % 7), zone);
}
export function weekDays(d: Date, weekStartsOn: WeekDay, zone = 'system'): Date[] {
  const first = startOfWeek(d, weekStartsOn, zone);
  return Array.from({ length: 7 }, (_, i) => addDays(first, i, zone));
}
export function monthGrid(d: Date, weekStartsOn: WeekDay, zone = 'system'): Date[][] {
  const start = startOfWeek(startOfMonth(d, zone), weekStartsOn, zone);
  return Array.from({ length: 6 }, (_, w) => Array.from({ length: 7 }, (_, i) => addDays(start, w * 7 + i, zone)));
}
export function hourOf(d: Date, zone = 'system'): number {
  const p = zonedParts(d, zone);
  return p.hour + p.minute / 60;
}

const cache = new Map<string, Intl.DateTimeFormat>();
const runtimeLocales = new WeakMap<typeof Intl.DateTimeFormat, string>();
function runtimeLocale(): string {
  let locale = runtimeLocales.get(Intl.DateTimeFormat);
  if (!locale) {
    locale = new Intl.DateTimeFormat().resolvedOptions().locale;
    runtimeLocales.set(Intl.DateTimeFormat, locale);
  }
  return locale;
}
/** Cached Intl formatter; an omitted locale uses the runtime locale. */
const fmt = (locale: string | undefined, opts: Intl.DateTimeFormatOptions) => {
  const key = `${locale ?? runtimeLocale()}|${JSON.stringify(opts)}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.DateTimeFormat(locale, opts);
    cache.set(key, f);
  }
  return f;
};

/** The clock options accepted by the scheduling blocks. */
export type HourCycle = 'h12' | 'h23';

/** "9:30 AM" or "09:30". */
export const formatTime = (d: Date, locale: string | undefined, hourCycle: HourCycle, zone = 'system') =>
  fmt(locale, {
    timeZone: zone === 'system' ? undefined : zone,
    hour: hourCycle === 'h12' ? 'numeric' : '2-digit',
    minute: '2-digit',
    hourCycle,
  }).format(d);
/** "9:30 AM–10:00 AM" or "09:30–10:00". */
export const formatRange = (
  start: Date,
  end: Date,
  locale: string | undefined,
  hourCycle: HourCycle,
  zone = 'system',
) => `${formatTime(start, locale, hourCycle, zone)}–${formatTime(end, locale, hourCycle, zone)}`;
/** Compact gutter label: "9 AM" or "09:00". */
export const formatHour = (hour: number, locale: string | undefined, hourCycle: HourCycle) =>
  fmt(locale, {
    hour: hourCycle === 'h12' ? 'numeric' : '2-digit',
    ...(hourCycle === 'h23' ? { minute: '2-digit' as const } : {}),
    hourCycle,
  }).format(new Date(2026, 0, 1, hour));
/** "Wednesday, April 15, 2026". */
export const formatFullDate = (d: Date, locale?: string, zone = 'system') =>
  fmt(locale, {
    timeZone: zone === 'system' ? undefined : zone,
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  }).format(d);
/** "Wednesday, April 15". */
export const formatDay = (d: Date, locale?: string, zone = 'system') =>
  fmt(locale, {
    timeZone: zone === 'system' ? undefined : zone,
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  }).format(d);
/** "April 2026". */
export const formatMonth = (d: Date, locale?: string, zone = 'system') =>
  fmt(locale, { timeZone: zone === 'system' ? undefined : zone, month: 'long', year: 'numeric' }).format(d);
/** "Apr 15". */
export const formatShort = (d: Date, locale?: string, zone = 'system') =>
  fmt(locale, { timeZone: zone === 'system' ? undefined : zone, month: 'short', day: 'numeric' }).format(d);
/** "Wed". */
export const formatWeekday = (d: Date, locale?: string, weekday: 'short' | 'long' = 'short', zone = 'system') =>
  fmt(locale, { timeZone: zone === 'system' ? undefined : zone, weekday }).format(d);

/** "Apr 13 – 19, 2026" (or across months / years). */
export function formatWeekRange(days: readonly Date[], locale?: string, zone = 'system'): string {
  const first = days[0];
  const last = days[days.length - 1];
  if (!first || !last) return '';
  if (locale && !locale.toLowerCase().startsWith('en'))
    return fmt(locale, {
      timeZone: zone === 'system' ? undefined : zone,
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    }).formatRange(first, last);
  if (sameMonth(first, last, zone))
    return `${formatShort(first, 'en-US', zone)} – ${zonedParts(last, zone).day}, ${zonedParts(last, zone).year}`;
  if (zonedParts(first, zone).year === zonedParts(last, zone).year)
    return `${formatShort(first, 'en-US', zone)} – ${formatShort(last, 'en-US', zone)}, ${zonedParts(last, zone).year}`;
  return `${formatShort(first, 'en-US', zone)}, ${zonedParts(first, zone).year} – ${formatShort(last, 'en-US', zone)}, ${zonedParts(last, zone).year}`;
}

/** Internal to blocks: Intl weekdays 1–7 become JS weekdays 0–6. */
export function weekendDays(locale?: string): WeekDay[] {
  try {
    const loc = new Intl.Locale(locale ?? new Intl.DateTimeFormat().resolvedOptions().locale) as Intl.Locale & {
      getWeekInfo?: () => { weekend: number[] };
      weekInfo?: { weekend: number[] };
    };
    const info = loc.getWeekInfo?.() ?? loc.weekInfo;
    if (info) return info.weekend.map((day) => (day % 7) as WeekDay);
  } catch {}
  return [6, 0];
}

import { CalendarCheck, Cog, Database, RefreshCw, ShieldCheck, Upload, type LucideIcon } from '@gntik-ai/icons';
import type { BadgeTone } from '@gntik-ai/ui';
import { dayKey } from './dates';

/** A scheduled item on a calendar. */
export interface ScheduleEvent {
  id: string;
  title: string;
  start: Date;
  end: Date;
  /** Key into the `kinds` map (job, deploy, review, backup, maintenance…). */
  kind?: string;
  /** Region, room or target, shown after the time. */
  location?: string;
}

export type EventTone = 'primary' | 'violet' | 'cyan' | 'amber' | 'neutral';

export interface EventKind {
  label: string;
  icon: LucideIcon;
  tone: EventTone;
}

/** Default kinds: brand green for jobs, categorical accents for the rest (never severity). */
export const defaultEventKinds: Record<string, EventKind> = {
  job: { label: 'Job', icon: RefreshCw, tone: 'primary' },
  deploy: { label: 'Deploy', icon: Upload, tone: 'violet' },
  review: { label: 'Review', icon: ShieldCheck, tone: 'cyan' },
  backup: { label: 'Backup', icon: Database, tone: 'amber' },
  maintenance: { label: 'Maintenance', icon: Cog, tone: 'neutral' },
};

const FALLBACK: EventKind = { label: 'Event', icon: CalendarCheck, tone: 'primary' };

export function kindOf(event: ScheduleEvent, kinds: Record<string, EventKind>): EventKind {
  return (event.kind ? kinds[event.kind] : undefined) ?? FALLBACK;
}

/** Token classes per tone. Text stays foreground on category tints (no contrast alias for them). */
export const TONE: Record<EventTone, { dot: string; soft: string; bar: string; icon: string; badge: BadgeTone }> = {
  primary: {
    dot: 'bg-primary',
    soft: 'bg-primary/12',
    bar: 'border-primary',
    icon: 'text-primary-text',
    badge: 'primary',
  },
  violet: {
    dot: 'bg-category-violet',
    soft: 'bg-category-violet/14',
    bar: 'border-category-violet',
    icon: 'text-foreground',
    badge: 'violet',
  },
  cyan: {
    dot: 'bg-category-cyan',
    soft: 'bg-category-cyan/14',
    bar: 'border-category-cyan',
    icon: 'text-foreground',
    badge: 'cyan',
  },
  amber: {
    dot: 'bg-category-amber',
    soft: 'bg-category-amber/16',
    bar: 'border-category-amber',
    icon: 'text-foreground',
    badge: 'amber',
  },
  neutral: {
    dot: 'bg-muted-foreground',
    soft: 'bg-secondary',
    bar: 'border-muted-foreground',
    icon: 'text-muted-foreground',
    badge: 'neutral',
  },
};

/** Events grouped by local day key, each day sorted by start. */
export function groupByDay(events: readonly ScheduleEvent[], timeZone = 'system'): Map<string, ScheduleEvent[]> {
  const map = new Map<string, ScheduleEvent[]>();
  for (const e of events) {
    const key = dayKey(e.start, timeZone);
    const list = map.get(key);
    if (list) list.push(e);
    else map.set(key, [e]);
  }
  for (const list of map.values()) list.sort((a, b) => a.start.getTime() - b.start.getTime());
  return map;
}

import { localeHourCycle, useOptionalI18n } from '@gntik-ai/ui';
import type { HourCycle } from './dates';

/** Map the existing public numeric clock API to scheduling's Intl options. */
function resolveHourCycle(locale?: string): HourCycle {
  return localeHourCycle(locale) === 12 ? 'h12' : 'h23';
}

/** Undefined outside a provider lets Intl use the runtime locale, as ui Calendar does. */
export function useSchedulingClock(override?: HourCycle) {
  const locale = useOptionalI18n()?.locale;
  return { locale, hourCycle: override ?? resolveHourCycle(locale) };
}
